import fs from 'node:fs/promises';
import path from 'node:path';

const KEY = /^[a-z][a-z0-9_-]*$/;

function failure(code, message) {
  return Object.assign(new Error(message), { code });
}

function invalid() {
  return failure('ERR_INVALID_BATCH', 'Invalid batch');
}

function corrupt(file) {
  return failure('ERR_CORRUPT_LEDGER', `Corrupt ledger file: ${file}`);
}

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function normalizeEntries(entries) {
  if (!Array.isArray(entries)) return null;
  const result = [];
  for (const entry of entries) {
    if (!isObject(entry) || typeof entry.key !== 'string' || !KEY.test(entry.key) || !Number.isSafeInteger(entry.delta)) return null;
    result.push({ key: entry.key, delta: entry.delta });
  }
  return result;
}

function validate(batch) {
  if (!isObject(batch) || typeof batch.id !== 'string' || !batch.id) throw invalid();
  const entries = normalizeEntries(batch.entries);
  if (!entries) throw invalid();
  return { id: batch.id, entries };
}

function sameEntries(a, b) {
  return a.length === b.length && a.every((entry, i) => entry.key === b[i].key && entry.delta === b[i].delta);
}

// Returns the new balances, or null if any resulting balance is not a safe integer.
function applyEntries(balances, entries) {
  const next = { ...balances };
  for (const { key, delta } of entries) {
    const value = (Object.hasOwn(next, key) ? next[key] : 0) + delta;
    if (!Number.isSafeInteger(value)) return null;
    next[key] = value;
  }
  return next;
}

function apply(state, batch) {
  const balances = applyEntries(state.balances, batch.entries);
  if (!balances) return null;
  return {
    revision: state.revision + 1,
    balances,
    receipts: [...state.receipts, { id: batch.id, entries: batch.entries }]
  };
}

async function readJson(io, file) {
  let text;
  try { text = await io.readFile(file, 'utf8'); }
  catch (error) { if (error.code === 'ENOENT') return undefined; throw error; }
  return JSON.parse(text);
}

function parseLedger(value, file) {
  if (value === undefined) return { revision: 0, balances: {}, receipts: [] };
  if (!isObject(value) || !Number.isSafeInteger(value.revision) || value.revision < 0 ||
      !isObject(value.balances) || !Array.isArray(value.receipts)) throw corrupt(file);
  const balances = {};
  for (const [key, amount] of Object.entries(value.balances)) {
    if (!KEY.test(key) || !Number.isSafeInteger(amount)) throw corrupt(file);
    balances[key] = amount;
  }
  const receipts = [];
  for (const receipt of value.receipts) {
    const entries = isObject(receipt) && typeof receipt.id === 'string' && receipt.id ? normalizeEntries(receipt.entries) : null;
    if (!entries) throw corrupt(file);
    receipts.push({ id: receipt.id, entries });
  }
  if (receipts.length !== value.revision) throw corrupt(file);
  return { revision: value.revision, balances, receipts };
}

function parsePending(value, file) {
  if (value === undefined) return null;
  if (!isObject(value) || !Number.isSafeInteger(value.base) || value.base < 0 ||
      typeof value.id !== 'string' || !value.id) throw corrupt(file);
  const entries = normalizeEntries(value.entries);
  if (!entries) throw corrupt(file);
  return { id: value.id, entries, base: value.base };
}

// Stage the full value, then atomically replace the target file.
async function save(io, directory, name, value) {
  const staging = path.join(directory, `${name}.tmp`);
  await io.writeFile(staging, JSON.stringify(value));
  await io.rename(staging, path.join(directory, `${name}.json`));
}

async function removePending(io, directory) {
  try { await io.unlink(path.join(directory, 'pending.json')); }
  catch (error) { if (error.code !== 'ENOENT') throw error; }
}

// Reads durable state and resolves any pending transaction in memory only.
// `action` is 'none', 'publish' (ledger lacks the pending batch), or 'cleanup'
// (ledger already contains it; only pending.json remains).
async function load(io, directory) {
  await io.mkdir(directory, { recursive: true });
  const ledgerFile = path.join(directory, 'ledger.json');
  const pendingFile = path.join(directory, 'pending.json');
  const state = parseLedger(await readJson(io, ledgerFile), ledgerFile);
  const pending = parsePending(await readJson(io, pendingFile), pendingFile);
  if (!pending) return { state, action: 'none' };
  const index = state.receipts.findIndex(receipt => receipt.id === pending.id);
  if (index !== -1) {
    if (index !== pending.base || !sameEntries(state.receipts[index].entries, pending.entries)) throw corrupt(pendingFile);
    return { state, action: 'cleanup' };
  }
  if (state.revision !== pending.base) throw corrupt(pendingFile);
  const next = apply(state, pending);
  if (!next) throw corrupt(pendingFile);
  return { state: next, action: 'publish' };
}

async function finish(io, directory, { state, action }) {
  if (action === 'publish') await save(io, directory, 'ledger', state);
  if (action !== 'none') await removePending(io, directory);
  return state;
}

export async function recoverLedger(directory, { io = fs } = {}) {
  return finish(io, directory, await load(io, directory));
}

export async function commitBatch(directory, batch, { io = fs, checkpoint } = {}) {
  batch = validate(batch);
  const loaded = await load(io, directory);
  const receipt = loaded.state.receipts.find(item => item.id === batch.id);
  let next = null;
  if (!receipt) {
    next = apply(loaded.state, batch);
    // Reject overflow before any durable change, including recovery of an earlier batch.
    if (!next) throw invalid();
  }
  const state = await finish(io, directory, loaded);
  if (receipt) {
    if (!sameEntries(receipt.entries, batch.entries)) throw failure('ERR_BATCH_CONFLICT', 'Batch ID already used');
    return state;
  }
  await save(io, directory, 'pending', { id: batch.id, entries: batch.entries, base: state.revision });
  if (checkpoint) await checkpoint('prepared');
  await save(io, directory, 'ledger', next);
  if (checkpoint) await checkpoint('published');
  await removePending(io, directory);
  if (checkpoint) await checkpoint('complete');
  return next;
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import { commitBatch, recoverLedger } from './src/ledger.js';

const b1 = { id: 'a', entries: [{ key: 'cash', delta: 5 }, { key: 'bank', delta: -2 }] };
const b2 = { id: 'b', entries: [{ key: 'cash', delta: 3 }, { key: 'cash', delta: 1 }] };
const final = { revision: 2, balances: { cash: 9, bank: -2 }, receipts: [b1, b2] };

function faulty(failAt, mode) {
  let n = 0;
  const io = {};
  for (const m of ['mkdir', 'readFile', 'writeFile', 'rename', 'unlink']) {
    io[m] = async (...args) => {
      if (n++ === failAt) {
        if (m === 'writeFile' && mode === 'partial') await fs.writeFile(args[0], String(args[1]).slice(0, 7));
        throw Object.assign(new Error('injected ' + m), { code: 'EIO' });
      }
      return fs[m](...args);
    };
  }
  return { io, count: () => n };
}

let cases = 0;
async function scenario(setup, run) {
  for (const mode of ['clean', 'partial']) {
    for (let failAt = 0; ; failAt++) {
      const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'ledger-fault-'));
      await setup(dir);
      const f = faulty(failAt, mode);
      let threw = false;
      try { await run(dir, f.io); } catch (e) { threw = true; assert.equal(e.code, 'EIO'); }
      // a retry may itself first hit recovery; also test recover-only path
      if (failAt % 2) assert.ok((await recoverLedger(dir)).revision >= 1);
      assert.deepEqual(await commitBatch(dir, b2), final);
      assert.deepEqual(await recoverLedger(dir), final);
      assert.deepEqual(await commitBatch(dir, b1), final);
      const files = (await fs.readdir(dir)).filter(x => x.endsWith('.json'));
      assert.deepEqual(files, ['ledger.json']);
      await fs.rm(dir, { recursive: true, force: true });
      cases++;
      if (!threw) break;
    }
  }
}

// Fault during second commit.
await scenario(dir => commitBatch(dir, b1), (dir, io) => commitBatch(dir, b2, { io }));

// Checkpoint interruptions at each phase, then fault during the recovering next commit.
for (const phase of ['prepared', 'published', 'complete']) {
  const err = new Error('stop');
  await scenario(async dir => {
    await commitBatch(dir, b1);
    await assert.rejects(commitBatch(dir, b2, { checkpoint: async p => { if (p === phase) throw err; } }), e => e === err);
  }, (dir, io) => recoverLedger(dir, { io }));
}

// Phase order.
{
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'ledger-fault-'));
  const seen = [];
  await commitBatch(dir, b1, { checkpoint: async p => { seen.push(p); } });
  assert.deepEqual(seen, ['prepared', 'published', 'complete']);
  seen.length = 0;
  await commitBatch(dir, b1, { checkpoint: async p => { seen.push(p); } });
  assert.deepEqual(seen, []);
  await assert.rejects(commitBatch(dir, { id: 'a', entries: [] }), { code: 'ERR_BATCH_CONFLICT' });
  await assert.rejects(commitBatch(dir, { id: 'x', entries: [{ key: 'Bad', delta: 1 }] }), { code: 'ERR_INVALID_BATCH' });
  await assert.rejects(commitBatch(dir, { id: '', entries: [] }), { code: 'ERR_INVALID_BATCH' });
  await assert.rejects(commitBatch(dir, { id: 'x', entries: [{ key: 'cash', delta: 1.5 }] }), { code: 'ERR_INVALID_BATCH' });
  // overflow with a pending earlier batch must not change durable data
  const stop = new Error('stop');
  await assert.rejects(commitBatch(dir, b2, { checkpoint: async p => { if (p === 'prepared') throw stop; } }), e => e === stop);
  const before = await fs.readFile(path.join(dir, 'ledger.json'), 'utf8');
  await assert.rejects(commitBatch(dir, { id: 'o', entries: [{ key: 'cash', delta: Number.MAX_SAFE_INTEGER }] }), { code: 'ERR_INVALID_BATCH' });
  assert.equal(await fs.readFile(path.join(dir, 'ledger.json'), 'utf8'), before);
  await fs.access(path.join(dir, 'pending.json'));
  assert.deepEqual(await commitBatch(dir, { id: 'e', entries: [] }), { ...final, revision: 3, receipts: [b1, b2, { id: 'e', entries: [] }] });
  await fs.writeFile(path.join(dir, 'ledger.json'), '{bad');
  await assert.rejects(recoverLedger(dir), SyntaxError);
  await fs.writeFile(path.join(dir, 'unrelated.txt'), 'x');
  await fs.rm(dir, { recursive: true, force: true });
}
console.log('ok', cases, 'fault cases');
